L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "\227\129\175\227\129\132\227\128\129\231\167\129\227\129\167\227\129\153\239\188\129\227\128\128\227\130\130\227\129\134\229\174\137\229\191\131\227\129\151\227\129\166\227\129\143\227\129\160\227\129\149\227\129\132\239\188\129\227\128\128\231\167\129\227\129\140\229\138\169\227\129\145\227\129\171\230\157\165\227\129\190\227\129\151\227\129\159\227\129\139\227\130\137\239\188\129"
