L19_1.m_Talk_THA = "\224\185\131\224\184\138\224\185\136\224\184\153\224\184\181\224\185\136\224\184\137\224\184\177\224\184\153\224\185\128\224\184\173\224\184\135! \224\185\132\224\184\161\224\185\136\224\184\149\224\185\137\224\184\173\224\184\135\224\184\129\224\184\165\224\184\177\224\184\167\224\184\153\224\184\176! \224\184\137\224\184\177\224\184\153\224\184\161\224\184\178\224\184\138\224\185\136\224\184\167\224\184\162\224\184\132\224\184\184\224\184\147\224\185\129\224\184\165\224\185\137\224\184\167!"
L19_1.m_Talk_VTN = "V\195\162ng, l\195\160 t\195\180i! \196\144\225\187\171ng lo! T\195\180i t\225\187\155i c\225\187\169u anh \196\145\195\162y!"
L19_1.m_Talk_SCN = "\229\175\185\239\188\140\230\152\175\230\136\145\239\188\129\230\148\190\229\191\131\229\144\167\239\188\129\230\136\145\230\157\165\228\186\134\239\188\140\228\189\160\228\188\154\230\178\161\228\186\139\231\154\132\239\188\129"
